import { useEffect, useMemo, useState } from 'react'
import {
  Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bath, Bell, Building2, CalendarDays, Check,
  CheckCheck, CheckCircle2, ChevronDown, CircleHelp, ClipboardCheck, ClipboardList, CreditCard,
  DoorOpen, Filter, Home, House, KeyRound, LayoutDashboard, LogOut, MapPin, Menu, MessageCircle,
  MoreHorizontal, Plus, Search, Send, Settings, ShieldCheck, Sparkles, Sun, Moon, Users, Wallet,
  Wrench, X, BedDouble, Upload, TrendingUp, Clock3, CircleDollarSign, FileText, Eye, EyeOff,
} from 'lucide-react'
import { useAuth } from './AuthContext.jsx'

const API = (import.meta.env.VITE_API_BASE_URL || 'http://localhost:8080/api').replace(/\/$/, '')
const STORE = { properties: 'haven.properties.v1', applications: 'haven.applications.v1', messages: 'haven.messages.v1', notifications: 'haven.notifications.v1', expenses: 'haven.expenses.v1' }
const photos = [
  'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1000&q=85',
  'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1000&q=85',
  'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=1000&q=85',
  'https://images.unsplash.com/photo-1564013799919-ab600027ffc6?auto=format&fit=crop&w=1000&q=85',
]
const demoProperties = [
  { id: 'demo-1', title: 'The Willow Residence', location: 'Gachibowli', city: 'Hyderabad', propertyType: 'Apartment', monthlyRent: 32000, bedrooms: 2, bathrooms: 2, available: false, status: 'Occupied', imageUrl: photos[0], ownerName: 'Aarav Mehta', description: 'A sunlit home with warm natural finishes and a leafy balcony.' },
  { id: 'demo-2', title: 'Palm House', location: 'Jubilee Hills', city: 'Hyderabad', propertyType: 'House', monthlyRent: 48500, bedrooms: 3, bathrooms: 3, available: true, status: 'Available', imageUrl: photos[1], ownerName: 'Aarav Mehta', description: 'A quiet, thoughtfully designed home close to cafés and parks.' },
  { id: 'demo-3', title: 'The Olive Studio', location: 'Kondapur', city: 'Hyderabad', propertyType: 'Studio', monthlyRent: 18500, bedrooms: 1, bathrooms: 1, available: true, status: 'Available', imageUrl: photos[2], ownerName: 'Aarav Mehta', description: 'A bright, efficient studio with everything close at hand.' },
  { id: 'demo-4', title: 'Garden Court', location: 'Madhapur', city: 'Hyderabad', propertyType: 'Apartment', monthlyRent: 27000, bedrooms: 2, bathrooms: 2, available: false, status: 'Under Maintenance', imageUrl: photos[3], ownerName: 'Aarav Mehta', description: 'A calm apartment with a private garden and generous light.' },
]
const seedApplications = [
  { id: 'a1', applicantName: 'Meera Nair', email: 'meera.n@example.com', phone: '+91 98765 44210', propertyTitle: 'Palm House', status: 'PENDING', appliedAt: 'Today' },
  { id: 'a2', applicantName: 'Kabir Shah', email: 'kabir.s@example.com', phone: '+91 98450 77120', propertyTitle: 'The Willow Residence', status: 'CHECKING', appliedAt: 'Yesterday' },
  { id: 'a3', applicantName: 'Sana Iyer', email: 'sana.iyer@example.com', phone: '+91 99801 34567', propertyTitle: 'The Olive Studio', status: 'APPROVED', appliedAt: 'Oct 10' },
]
const seedNotifications = [
  { id: 1, title: 'Rent due soon', detail: 'Your rent of ₹32,000 is due in 3 days.', kind: 'payment', read: false, time: '10 min ago' },
  { id: 2, title: 'Maintenance update', detail: 'Garden Court maintenance is scheduled for Friday.', kind: 'maintenance', read: false, time: '1 hour ago' },
  { id: 3, title: 'New message', detail: 'Meera sent you a message about Palm House.', kind: 'message', read: true, time: 'Yesterday' },
]
const seedMessages = [
  { id: 'c1', name: 'Meera Nair', property: 'Palm House', initials: 'MN', online: true, messages: [{ from: 'them', text: 'Hi! Could you share a little more about the move-in date?', time: '10:42 AM' }, { from: 'me', text: 'Of course — the home is ready from the 1st of next month.', time: '10:45 AM' }, { from: 'them', text: 'That works perfectly. I’ll send my application this afternoon.', time: '10:47 AM' }] },
  { id: 'c2', name: 'Kabir Shah', property: 'The Willow Residence', initials: 'KS', online: false, messages: [{ from: 'them', text: 'Thank you for arranging the viewing. The apartment is lovely.', time: 'Yesterday' }] },
  { id: 'c3', name: 'Sana Iyer', property: 'The Olive Studio', initials: 'SI', online: true, messages: [{ from: 'them', text: 'Is parking included with the lease?', time: 'Mon' }] },
]
const money = (value) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(value || 0))
const readStore = (key, fallback) => { try { const stored = localStorage.getItem(key); return stored ? JSON.parse(stored) : fallback } catch { return fallback } }
const roleHome = { tenant: '/tenant', landlord: '/landlord', admin: '/admin' }
const roleName = { tenant: 'Tenant', landlord: 'Landlord', admin: 'Admin' }
const pageForPath = (path) => ({ '/Act': 'discover', '/': 'discover', '/discover': 'discover', '/tenant': 'dashboard', '/landlord': 'dashboard', '/admin': 'dashboard', '/properties': 'properties', '/applications': 'applications', '/finances': 'finances', '/messages': 'messages', '/users': 'users' }[path] || 'discover')

export default function App() {
  const { user, signIn, signOut } = useAuth()
  const role = user?.role || 'tenant'
  const [path, setPath] = useState(window.location.pathname)
  const [page, setPage] = useState(pageForPath(window.location.pathname))
  const [properties, setProperties] = useState(() => readStore(STORE.properties, demoProperties))
  const [applications, setApplications] = useState(() => user?.role === 'tenant'
    ? [{ id: 'tenant-demo', applicantName: user.name, email: user.email, propertyTitle: 'The Willow Residence', status: 'APPROVED', appliedAt: 'Oct 01' }]
    : readStore(STORE.applications, seedApplications))
  const [notifications, setNotifications] = useState(() => readStore(STORE.notifications, seedNotifications))
  const [messages, setMessages] = useState(() => readStore(STORE.messages, seedMessages))
  const [expenses, setExpenses] = useState(() => readStore(STORE.expenses, [{ id: 1, label: 'Plumbing repair', category: 'Repairs', amount: 6800, date: 'Oct 12' }, { id: 2, label: 'Property tax', category: 'Taxes', amount: 12400, date: 'Oct 09' }, { id: 3, label: 'Common utilities', category: 'Utilities', amount: 3850, date: 'Oct 06' }]))
  const [activeChat, setActiveChat] = useState('c1')
  const [query, setQuery] = useState('')
  const [filter, setFilter] = useState('All homes')
  const [modal, setModal] = useState('')
  const [editing, setEditing] = useState(null)
  const [menuOpen, setMenuOpen] = useState(false)
  const [noticeOpen, setNoticeOpen] = useState(false)
  const [notice, setNotice] = useState('')
  const [mobileNav, setMobileNav] = useState(false)
  const [online, setOnline] = useState(false)
  const [form, setForm] = useState({ title: '', location: '', city: 'Hyderabad', propertyType: 'Apartment', monthlyRent: '', bedrooms: 2, bathrooms: 1, description: '', imageUrl: '', available: true })
  const [authMode, setAuthMode] = useState('signin')
  const [authRole, setAuthRole] = useState('tenant')
  const [authForm, setAuthForm] = useState({ name: '', email: '', password: '' })
  const [authError, setAuthError] = useState('')
  const [messageDraft, setMessageDraft] = useState('')
  const [expenseForm, setExpenseForm] = useState({ label: '', category: 'Repairs', amount: '' })
  const [showPassword, setShowPassword] = useState(false)

  useEffect(() => {
    const onPop = () => { const p = window.location.pathname; setPath(p); setPage(pageForPath(p)) }
    window.addEventListener('popstate', onPop)
    return () => window.removeEventListener('popstate', onPop)
  }, [])
  useEffect(() => { localStorage.setItem(STORE.properties, JSON.stringify(properties)) }, [properties])
  useEffect(() => { if (role !== 'tenant') localStorage.setItem(STORE.applications, JSON.stringify(applications)) }, [applications, role])
  useEffect(() => { localStorage.setItem(STORE.notifications, JSON.stringify(notifications)) }, [notifications])
  useEffect(() => { localStorage.setItem(STORE.messages, JSON.stringify(messages)) }, [messages])
  useEffect(() => { localStorage.setItem(STORE.expenses, JSON.stringify(expenses)) }, [expenses])
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(''), 3600); return () => clearTimeout(timer) }, [notice])
  useEffect(() => {
    if (user && ['/login', '/signup'].includes(window.location.pathname)) go(roleHome[user.role])
    if (user && ['/tenant', '/landlord', '/admin'].includes(window.location.pathname) && window.location.pathname !== roleHome[user.role]) go(roleHome[user.role])
    if (user && window.location.pathname === '/users' && user.role !== 'admin') go(roleHome[user.role])
    if (user && ['/properties', '/finances'].includes(window.location.pathname) && !['landlord', 'admin'].includes(user.role)) go(roleHome[user.role])
  }, [user])

  function go(nextPath) {
    window.history.pushState({}, '', nextPath)
    setPath(nextPath); setPage(pageForPath(nextPath)); setMobileNav(false); setNoticeOpen(false)
  }
  function openPage(next) {
    if (next === 'dashboard') go(roleHome[user?.role] || '/login')
    else if (next === 'discover') go('/Act')
    else go(`/${next}`)
  }
  const ManageIcon = role === 'landlord' ? Wallet : ShieldCheck
  const unread = notifications.filter(item => !item.read).length
  const filteredProperties = useMemo(() => properties.filter(p => {
    const haystack = `${p.title} ${p.location} ${p.city} ${p.propertyType}`.toLowerCase()
    return haystack.includes(query.toLowerCase()) && (filter === 'All homes' || p.status === filter || (filter === 'Available' && p.available))
  }), [properties, query, filter])
  const activeConversation = messages.find(chat => chat.id === activeChat) || messages[0]
  const occupied = properties.filter(p => p.status === 'Occupied' || (!p.status && !p.available)).length
  const occupancy = properties.length ? Math.round(occupied / properties.length * 100) : 0

  async function loadProperties() {
    try {
      const [pRes, aRes] = await Promise.all([fetch(`${API}/properties`), role === 'tenant' ? Promise.resolve(null) : fetch(`${API}/applications`)] )
      if (!pRes.ok) throw new Error('API unavailable')
      const list = await pRes.json()
      const localProperties = readStore(STORE.properties, [])
      setProperties(list.map(p => { const preview = localProperties.find(item => String(item.id) === String(p.id)); return { ...p, imageUrl: preview?.imageUrl || p.imageUrl, status: preview?.status || p.status || (p.available ? 'Available' : 'Occupied') } }))
      setOnline(true)
      if (role === 'tenant') {
        setApplications([{ id: 'tenant-demo', applicantName: user.name, email: user.email, propertyTitle: 'The Willow Residence', status: 'APPROVED', appliedAt: 'Oct 01' }])
      } else if (aRes?.ok) {
        const records = await aRes.json()
        const localApplications = readStore(STORE.applications, [])
        setApplications(records.map(app => { const preview = localApplications.find(item => String(item.id) === String(app.id)); return preview?.status === 'CHECKING' ? { ...app, status: 'CHECKING' } : app }))
      }
    } catch { setOnline(false) }
  }
  useEffect(() => { if (user) loadProperties() }, [user])

  function submitAuth(event) {
    event.preventDefault(); setAuthError('')
    if (!authForm.email.includes('@')) return setAuthError('Enter a valid email address to continue.')
    if (authForm.password.length < 4) return setAuthError('Use at least 4 characters for this demo sign-in.')
    signIn({ ...authForm, role: authRole })
    go(roleHome[authRole])
    setNotice(`Welcome to Haven, ${authForm.name || authForm.email.split('@')[0]}.`)
  }
  function demoSocial(provider) { signIn({ name: `${roleName[authRole]} demo`, email: `${authRole}@haven.demo`, role: authRole }); go(roleHome[authRole]); setNotice(`Signed in with ${provider} demo.`) }
  function logout() { signOut(); go('/login') }
  function requireRole(allowed) {
    if (!user) { go('/login'); return false }
    if (!allowed.includes(role)) { go(roleHome[role]); setNotice(`That page is for ${allowed.map(r => roleName[r]).join(' or ')} accounts.`); return false }
    return true
  }

  async function saveProperty(event) {
    event.preventDefault()
    const payload = { ...form, monthlyRent: Number(form.monthlyRent), bedrooms: Number(form.bedrooms), bathrooms: Number(form.bathrooms), ownerName: user?.name || 'Haven Landlord', available: form.status ? form.status === 'Available' : form.available }
    payload.status = form.status || (payload.available ? 'Available' : 'Occupied')
    const apiPayload = { ...payload, imageUrl: payload.imageUrl?.startsWith('data:') ? '' : payload.imageUrl }
    try {
      if (editing && !String(editing.id).startsWith('demo-') && !String(editing.id).startsWith('local-')) {
        const response = await fetch(`${API}/properties/${editing.id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(apiPayload) })
        if (!response.ok) throw new Error('Unable to update listing')
        const saved = await response.json(); setProperties(prev => prev.map(p => p.id === editing.id ? { ...saved, imageUrl: payload.imageUrl || saved.imageUrl, status: payload.status } : p)); setOnline(true)
      } else if (!editing) {
        const response = await fetch(`${API}/properties`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(apiPayload) })
        if (!response.ok) throw new Error('Backend is offline')
        const saved = await response.json(); setProperties(prev => [{ ...saved, imageUrl: payload.imageUrl || saved.imageUrl, status: payload.status }, ...prev]); setOnline(true)
      } else setProperties(prev => prev.map(p => p.id === editing.id ? { ...payload, id: editing.id } : p))
      setNotice(editing ? 'Listing updated.' : online ? 'Property published.' : 'Property saved to this browser preview.')
    } catch {
      if (editing) setProperties(prev => prev.map(p => p.id === editing.id ? { ...payload, id: editing.id } : p))
      else setProperties(prev => [{ ...payload, id: `local-${Date.now()}` }, ...prev])
      setNotice('Saved in browser preview. Connect the backend to persist this listing in MySQL.')
    }
    setModal(''); setEditing(null); setForm({ title: '', location: '', city: 'Hyderabad', propertyType: 'Apartment', monthlyRent: '', bedrooms: 2, bathrooms: 1, description: '', imageUrl: '', available: true })
  }
  async function changeApplication(app, status) {
    try {
      const response = await fetch(`${API}/applications/${app.id}/status?status=${status}`, { method: 'PATCH' })
      if (!response.ok) throw new Error()
      const saved = await response.json(); setApplications(prev => prev.map(a => a.id === app.id ? saved : a)); setOnline(true)
    } catch { setApplications(prev => prev.map(a => a.id === app.id ? { ...a, status } : a)) }
    setNotice(`Application moved to ${status === 'CHECKING' ? 'background check' : status.toLowerCase()}.`)
  }
  function sendMessage(event) {
    event.preventDefault(); if (!messageDraft.trim() || !activeConversation) return
    setMessages(prev => prev.map(chat => chat.id === activeChat ? { ...chat, messages: [...chat.messages, { id: Date.now(), from: 'me', text: messageDraft.trim(), time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }] } : chat))
    setMessageDraft('')
  }
  function markRead() { setNotifications(prev => prev.map(item => ({ ...item, read: true }))); setNotice('All notifications marked as read.') }
  function addExpense(event) { event.preventDefault(); setExpenses(prev => [{ ...expenseForm, amount: Number(expenseForm.amount), date: 'Today', id: Date.now() }, ...prev]); setExpenseForm({ label: '', category: 'Repairs', amount: '' }); setModal(''); setNotice('Expense added to your ledger.') }
  function uploadImage(event) {
    const file = event.target.files?.[0]; if (!file) return
    if (!file.type.startsWith('image/') || file.size > 2_000_000) return setNotice('Choose an image smaller than 2 MB.')
    const reader = new FileReader(); reader.onload = () => setForm(prev => ({ ...prev, imageUrl: String(reader.result) })); reader.readAsDataURL(file)
  }

  if (!user && !['/Act', '/discover', '/'].includes(path)) return <LoginPage {...{ authMode, setAuthMode, authRole, setAuthRole, authForm, setAuthForm, authError, showPassword, setShowPassword, submitAuth, demoSocial, go }} />

  const navItems = role === 'tenant'
    ? [{ id: 'dashboard', label: 'My home', icon: LayoutDashboard }, { id: 'discover', label: 'Find a home', icon: Search }, { id: 'applications', label: 'My applications', icon: ClipboardList }, { id: 'messages', label: 'Messages', icon: MessageCircle }]
    : role === 'landlord'
      ? [{ id: 'dashboard', label: 'Overview', icon: LayoutDashboard }, { id: 'properties', label: 'My properties', icon: Building2 }, { id: 'applications', label: 'Applications', icon: ClipboardList }, { id: 'finances', label: 'Finances', icon: Wallet }, { id: 'messages', label: 'Messages', icon: MessageCircle }]
      : [{ id: 'dashboard', label: 'Overview', icon: LayoutDashboard }, { id: 'users', label: 'User directory', icon: Users }, { id: 'properties', label: 'All properties', icon: Building2 }, { id: 'applications', label: 'Applications', icon: ClipboardList }, { id: 'messages', label: 'Messages', icon: MessageCircle }]

  const goNav = (id) => {
    if (['properties', 'finances'].includes(id) && !requireRole(['landlord', 'admin'])) return
    if (id === 'users' && !requireRole(['admin'])) return
    if (id === 'applications' && role === 'tenant') { setPage('applications'); go('/applications'); return }
    openPage(id)
  }

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
      <button className="brand" onClick={() => go(roleHome[role])}><span className="brand-mark"><House size={19}/></span><span className="brand-copy"><b>haven<span>.</span></b><small>PROPERTY, MADE SIMPLE</small></span></button>
      <div className="workspace-switch"><span className="workspace-mark">{roleName[role][0]}</span><span><small>YOUR WORKSPACE</small><b>{roleName[role]} portal</b></span><ChevronDown size={15}/></div>
      <span className="nav-caption">WORKSPACE</span>
      <nav className="side-nav">{navItems.map(item => <button key={item.id} className={`nav-item ${(page === item.id || (item.id === 'discover' && page === 'discover')) ? 'active' : ''}`} onClick={() => goNav(item.id)}><item.icon size={17}/><span>{item.label}</span>{item.id === 'messages' && <i className="nav-dot"/>}</button>)}</nav>
      {role !== 'tenant' && <><span className="nav-caption secondary-caption">MANAGE</span><nav className="side-nav"><button className={`nav-item ${page === 'finances' ? 'active' : ''}`} onClick={() => goNav(role === 'landlord' ? 'finances' : 'users')}><ManageIcon size={17}/><span>{role === 'landlord' ? 'Rent & expenses' : 'Access & roles'}</span></button></nav></>}
      <div className="sidebar-bottom"><div className="sidebar-tip"><div className="tip-icon"><Sparkles size={15}/></div><b>A smoother rental, starts here.</b><p>Keep the details together and the busywork light.</p><button onClick={() => setNotice('Help centre is coming soon.')}>Visit help centre <ArrowUpRight size={13}/></button></div><div className="profile-row"><span className="avatar">{(user?.name || 'G').slice(0, 1).toUpperCase()}</span><span className="profile-copy"><b>{user?.name || 'Browsing as guest'}</b><small>{user ? `${roleName[role]} account` : 'Public preview'}</small></span>{user ? <button className="bare-icon" title="Sign out" onClick={logout}><LogOut size={16}/></button> : <button className="bare-link" onClick={() => go('/login')}>Sign in</button>}</div></div>
    </aside>
    {mobileNav && <button className="mobile-scrim" onClick={() => setMobileNav(false)} aria-label="Close navigation"/>}
    <main className="main">
      <header className="topbar"><button className="mobile-menu icon-button" onClick={() => setMobileNav(!mobileNav)} aria-label="Open navigation"><Menu size={20}/></button><div className="breadcrumbs"><span>Workspace</span><i>/</i><b>{navItems.find(n => n.id === page)?.label || ({ finances: 'Rent & expenses', users: 'User directory' }[page]) || 'Find a home'}</b></div><div className="top-actions"><div className={`api-status ${online ? 'is-online' : ''}`}><span/>{online ? 'Synced with your property API' : 'Preview data'}</div><button className="theme-button" onClick={() => window.dispatchEvent(new Event('haven:toggle-theme'))} aria-label="Toggle theme"><Sun size={16}/></button><div className="notification-wrap"><button className={`icon-button notification-button ${noticeOpen ? 'pressed' : ''}`} onClick={() => { setNoticeOpen(!noticeOpen); setMenuOpen(false) }} aria-label="Notifications"><Bell size={17}/>{unread > 0 && <i>{unread}</i>}</button>{noticeOpen && <div className="notification-menu"><div className="dropdown-head"><div><b>Notifications</b><small>{unread} unread updates</small></div><button className="bare-link" onClick={markRead}><CheckCheck size={14}/> Mark all read</button></div>{notifications.map(item => <div key={item.id} className={`notification-item ${item.read ? '' : 'unread'}`}><span className={`notification-symbol ${item.kind}`}>{item.kind === 'payment' ? <CircleDollarSign size={16}/> : item.kind === 'message' ? <MessageCircle size={16}/> : <Wrench size={16}/>}</span><div><b>{item.title}</b><p>{item.detail}</p><small>{item.time}</small></div></div>)}{notifications.length === 0 && <Empty icon={Bell} title="You're all caught up" detail="New updates will appear here."/>}</div>}</div>{user ? <div className="account-menu-wrap"><button className="account-button" onClick={() => { setMenuOpen(!menuOpen); setNoticeOpen(false) }}><span className="avatar small-avatar">{user.name.slice(0,1).toUpperCase()}</span><span className="account-name">{user.name.split(' ')[0]}</span><ChevronDown size={14}/></button>{menuOpen && <div className="account-dropdown"><div className="account-summary"><b>{user.name}</b><span>{user.email}</span><em>{roleName[role]} account</em></div><button onClick={() => setNotice('Profile settings are coming soon.')}><Settings size={15}/> Account settings</button><button onClick={logout}><LogOut size={15}/> Sign out</button></div>}</div> : <button className="btn-primary guest-signin" onClick={() => go('/login')}>Sign in <ArrowRight size={14}/></button>}</div></header>
      {notice && <div className="toast"><CheckCircle2 size={16}/>{notice}<button onClick={() => setNotice('')} aria-label="Dismiss"><X size={15}/></button></div>}
      <div className="page-body">
        {page === 'dashboard' && <Dashboard {...{ role, user, properties, applications, occupancy, goNav, setNotice, openPage }} />}
        {page === 'discover' && <DiscoverPage {...{ properties: filteredProperties, allProperties: properties, query, setQuery, filter, setFilter, setModal, setNotice, requireRole, role }} />}
        {page === 'properties' && <PropertiesPage {...{ properties, setProperties, setModal, setEditing, setForm, setNotice }} />}
        {page === 'applications' && <ApplicationsPage {...{ role, applications, changeApplication, goNav }} />}
        {page === 'finances' && <FinancesPage {...{ expenses, setModal, setNotice, properties }} />}
        {page === 'messages' && <MessagesPage {...{ messages, activeChat, setActiveChat, activeConversation, messageDraft, setMessageDraft, sendMessage, role }} />}
        {page === 'users' && <UsersPage {...{ setNotice }} />}
      </div>
      <footer className="footer"><span>© 2026 Haven Rental Platform</span><span>Good homes. Clearer days. <span>✳</span></span></footer>
    </main>
    {modal === 'property' && <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && setModal('')}><div className="modal form-modal"><div className="modal-heading"><div><div className="eyebrow">PROPERTY DETAILS</div><h2>{editing ? 'Update your' : 'Add a'} <i>property.</i></h2><p>Share the details tenants need to find their next home.</p></div><button className="modal-close" onClick={() => setModal('')} aria-label="Close"><X size={18}/></button></div><form onSubmit={saveProperty}><div className="form-grid"><label className="span-two">Property name<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="e.g. The Willow Residence"/></label><label className="span-two">Street / neighbourhood<input required value={form.location} onChange={e => setForm({ ...form, location: e.target.value })} placeholder="e.g. Jubilee Hills"/></label><label>City<input required value={form.city} onChange={e => setForm({ ...form, city: e.target.value })}/></label><label>Unit type<select value={form.propertyType} onChange={e => setForm({ ...form, propertyType: e.target.value })}><option>Apartment</option><option>House</option><option>Studio</option><option>Villa</option></select></label><label>Monthly rent (₹)<input required min="1" type="number" value={form.monthlyRent} onChange={e => setForm({ ...form, monthlyRent: e.target.value })} placeholder="32000"/></label><label>Listing status<select value={form.status || 'Available'} onChange={e => setForm({ ...form, status: e.target.value })}><option>Available</option><option>Occupied</option><option>Under Maintenance</option></select></label><label>Bedrooms<input min="0" type="number" value={form.bedrooms} onChange={e => setForm({ ...form, bedrooms: e.target.value })}/></label><label>Bathrooms<input min="0" type="number" value={form.bathrooms} onChange={e => setForm({ ...form, bathrooms: e.target.value })}/></label><label className="span-two">Description<textarea rows="3" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="A few words about what makes this place special"/></label><label className="span-two upload-label"><span>Property image</span><span className="upload-control"><Upload size={15}/> Choose image <small>up to 2 MB</small><input type="file" accept="image/*" onChange={uploadImage}/></span>{form.imageUrl && <img className="upload-preview" src={form.imageUrl} alt="Property preview"/>}</label></div><button className="btn-primary full-btn" type="submit"><Check size={16}/>{editing ? 'Save changes' : 'Add property'}</button></form></div></div>}
    {modal === 'expense' && <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && setModal('')}><div className="modal form-modal compact-modal"><div className="modal-heading"><div><div className="eyebrow">RENT LEDGER</div><h2>Log an <i>expense.</i></h2></div><button className="modal-close" onClick={() => setModal('')}><X size={18}/></button></div><form onSubmit={addExpense}><label>Description<input required value={expenseForm.label} onChange={e => setExpenseForm({ ...expenseForm, label: e.target.value })} placeholder="e.g. Kitchen tap repair"/></label><div className="form-grid"><label>Category<select value={expenseForm.category} onChange={e => setExpenseForm({ ...expenseForm, category: e.target.value })}><option>Repairs</option><option>Taxes</option><option>Utilities</option></select></label><label>Amount (₹)<input type="number" min="1" required value={expenseForm.amount} onChange={e => setExpenseForm({ ...expenseForm, amount: e.target.value })}/></label></div><button className="btn-primary full-btn" type="submit">Add to ledger <ArrowRight size={15}/></button></form></div></div>}
  </div>
}

function Dashboard({ role, user, properties, applications, occupancy, goNav, setNotice, openPage }) {
  if (role === 'tenant') return <section className="dashboard-page"><PageHeading eyebrow="TENANT DASHBOARD" title={<>Welcome home, <i>{user.name.split(' ')[0]}.</i></>} subtitle="Your rental, all in one place." action={<button className="btn-secondary" onClick={() => openPage('discover')}>Explore homes <ArrowUpRight size={15}/></button>}/><div className="tenant-hero"><div className="tenant-home-photo" style={{ backgroundImage: `url(${photos[0]})` }}><span className="lease-status"><span/> ACTIVE LEASE</span></div><div className="tenant-home-details"><div className="eyebrow">YOUR CURRENT HOME</div><h2>The Willow Residence</h2><p className="property-location"><MapPin size={15}/> Gachibowli, Hyderabad</p><div className="tenant-meta"><span><CalendarDays size={16}/> Lease ends <b>30 Sep 2027</b></span><span><KeyRound size={16}/> 2 bed · 2 bath</span></div><div className="rent-due"><div><small>NEXT RENT PAYMENT</small><b>₹32,000 <em>due Nov 1</em></b></div><button className="btn-primary" onClick={() => setNotice('Payments are in preview mode. Connect a payment provider to accept rent.')}>Pay rent <ArrowRight size={15}/></button></div></div></div><div className="stat-grid three"><Metric icon={CircleDollarSign} label="Monthly rent" value="₹32,000" tone="sage" note="Due on the 1st"/><Metric icon={ClipboardCheck} label="Lease status" value="Active" tone="blue" note="11 months remaining"/><Metric icon={Wrench} label="Maintenance" value="1 request" tone="amber" note="Kitchen tap · In progress"/></div><div className="two-col"><section className="surface-card"><CardHeading title="Recent activity" detail="A quick look at your home"/><ActivityRow icon={CheckCircle2} title="Lease renewed" detail="Your new term began Oct 1" time="Oct 01"/><ActivityRow icon={Wrench} title="Maintenance scheduled" detail="Kitchen tap repair · Friday" time="Oct 12"/><ActivityRow icon={CreditCard} title="Rent payment received" detail="October rent · ₹32,000" time="Oct 01"/></section><section className="surface-card maintenance-card"><span className="soft-icon amber"><Wrench size={19}/></span><div className="eyebrow">MAINTENANCE REQUEST</div><h3>Kitchen tap repair</h3><p>Your landlord has scheduled a plumber for Friday, Oct 17 between 10:00 AM and 12:00 PM.</p><span className="status-pill status-checking"><span/> Scheduled</span><button className="inline-action" onClick={() => goNav('messages')}>Message landlord <ArrowRight size={14}/></button></section></div></section>
  if (role === 'admin') return <section className="dashboard-page"><PageHeading eyebrow="PLATFORM OVERVIEW" title={<>A clearer view of <i>Haven.</i></>} subtitle="Platform health, users, and rentals at a glance."/><div className="stat-grid four"><Metric icon={Users} label="Platform users" value="1,284" tone="blue" change="+12.8% this month"/><Metric icon={Building2} label="Active listings" value={properties.length + 132} tone="sage" change="+8.2% this month"/><Metric icon={ClipboardList} label="Applications" value="284" tone="amber" change="+14 today"/><Metric icon={Activity} label="Platform uptime" value="99.9%" tone="purple" change="All systems operational"/></div><div className="two-col"><section className="surface-card"><CardHeading title="Platform activity" detail="The last 7 days" action={<button className="bare-link" onClick={() => setNotice('Showing the last 7 days.')}>This week <ChevronDown size={13}/></button>}/><MiniChart/><div className="chart-legend"><span><i className="legend-sage"/> New users</span><span><i className="legend-blue"/> New listings</span></div></section><section className="surface-card"><CardHeading title="Recent platform users" detail="Latest accounts" action={<button className="bare-link" onClick={() => goNav('users')}>All users <ArrowRight size={13}/></button>}/><UserRow initials="AN" name="Aarav Nair" email="aarav.n@example.com" role="Landlord"/><UserRow initials="MK" name="Mira Kapoor" email="mira.k@example.com" role="Tenant"/><UserRow initials="RV" name="Rohan Verma" email="rohan.v@example.com" role="Tenant"/><UserRow initials="PS" name="Priya Shah" email="priya.s@example.com" role="Landlord"/></section></div><section className="surface-card admin-health"><span className="health-check"><Check size={17}/></span><div><b>Everything is running smoothly</b><p>Property API connected · Database healthy · Notifications operational</p></div><span className="status-pill status-approved">All systems normal</span></section></section>
  return <LandlordDashboard {...{ user, properties, applications, occupancy, goNav }} />
}

function LandlordDashboard({ user, properties, applications, occupancy, goNav }) {
  const collected = properties.filter(p => p.status === 'Occupied').reduce((sum, p) => sum + Number(p.monthlyRent || 0), 0)
  return <section className="dashboard-page"><PageHeading eyebrow="LANDLORD DASHBOARD" title={<>Good morning, <i>{user.name.split(' ')[0]}.</i></>} subtitle="Here’s the latest from your property portfolio." action={<button className="btn-primary" onClick={() => goNav('properties')}><Plus size={16}/> Add a property</button>}/><div className="stat-grid four"><Metric icon={Building2} label="Total properties" value={properties.length} tone="sage" note="Across your portfolio"/><Metric icon={TrendingUp} label="Occupancy rate" value={`${occupancy}%`} tone="blue" change="Across active listings"/><Metric icon={CircleDollarSign} label="Monthly rent" value={money(collected || 32000)} tone="amber" change="Expected this month"/><Metric icon={ClipboardList} label="Open applications" value={applications.filter(a => !['APPROVED', 'REJECTED'].includes(a.status)).length} tone="purple" note="Ready for your review"/></div><div className="landlord-grid"><section className="surface-card rent-chart-card"><CardHeading title="Rent overview" detail="Your portfolio, October 2026" action={<button className="bare-link">This month <ChevronDown size={13}/></button>}/><div className="rent-totals"><div><small>COLLECTED</small><b>₹1,12,000</b><span className="positive"><ArrowUpRight size={13}/> 8.4% vs last month</span></div><div><small>PENDING</small><b>₹32,000</b><span className="muted-copy">1 payment due Nov 1</span></div></div><MiniChart/><div className="chart-legend"><span><i className="legend-sage"/> Rent collected</span><span><i className="legend-cream"/> Pending rent</span></div></section><section className="surface-card"><CardHeading title="Needs your attention" detail="A few things to take care of"/><Attention icon={ClipboardList} title="New tenant application" detail="Meera Nair · Palm House" action="Review" onClick={() => goNav('applications')}/><Attention icon={Wrench} title="Maintenance follow-up" detail="Garden Court · Plumbing" action="View" onClick={() => goNav('properties')}/><Attention icon={CircleDollarSign} title="Rent payment pending" detail="The Willow Residence · ₹32,000" action="Details" onClick={() => goNav('finances')}/></section></div><section className="surface-card"><CardHeading title="Your properties" detail="A snapshot of your active listings" action={<button className="bare-link" onClick={() => goNav('properties')}>View all <ArrowRight size={13}/></button>}/><PropertyTable properties={properties.slice(0, 4)}/></section></section>
}

function DiscoverPage({ properties, allProperties, query, setQuery, filter, setFilter, setModal, setNotice, requireRole, role }) {
  const [selected, setSelected] = useState(null)
  return <section className="dashboard-page"><PageHeading eyebrow="THE HAVEN COLLECTION" title={<>Find a place that <i>feels right.</i></>} subtitle="A considered collection of homes for every next chapter."/><div className="discover-banner"><div><div className="eyebrow">A BETTER WAY TO FIND HOME</div><h2>Room for the life<br/>you’re building.</h2><p>Find the right place, then make it yours.</p></div><div className="banner-illustration"><div className="banner-sun"/><div className="banner-house"><span/><i/><b/></div></div></div><section className="surface-card listing-surface"><div className="listing-toolbar"><div className="searchbox"><Search size={17}/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search neighbourhood, city or home"/>{query && <button onClick={() => setQuery('')}><X size={15}/></button>}</div><label className="select-filter"><Filter size={15}/><select value={filter} onChange={e => setFilter(e.target.value)}><option>All homes</option><option>Available</option><option>Occupied</option><option>Under Maintenance</option></select></label><span className="result-count">{properties.length} homes</span></div><div className="property-grid">{properties.map((property, index) => <PropertyCard key={property.id} property={property} onClick={() => setSelected(property)} index={index}/>)}</div>{properties.length === 0 && <Empty icon={House} title="No homes match your search" detail="Try a different neighbourhood or clear your filters." action={<button className="btn-secondary" onClick={() => { setQuery(''); setFilter('All homes') }}>Clear filters</button>}/>}<div className="map-section"><div className="map-copy"><span className="eyebrow">GET TO KNOW THE AREA</span><h3>Explore homes <i>by location.</i></h3><p>See how these neighbourhoods connect to the places that matter to you.</p><div className="map-legend"><span><i/> Available home</span><span><i/> Occupied home</span></div></div><div className="map-canvas"><div className="map-river"/><span className="map-road road-a"/><span className="map-road road-b"/><span className="map-label label-one">Gachibowli</span><span className="map-label label-two">Madhapur</span><span className="map-label label-three">Jubilee Hills</span>{allProperties.slice(0, 4).map((p, i) => <button key={p.id} style={{ left: `${22 + i * 19}%`, top: `${30 + (i % 2) * 33}%` }} className={`map-pin ${p.available ? 'available' : ''}`} onClick={() => setSelected(p)} aria-label={`View ${p.title}`}><MapPin size={15}/></button>)}<div className="map-attribution">Map preview · Hyderabad</div></div></div></section>{selected && <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && setSelected(null)}><div className="modal property-detail-modal"><button className="modal-close" onClick={() => setSelected(null)}><X size={18}/></button><img className="modal-cover" src={selected.imageUrl || photos[0]} alt={selected.title}/><div className="modal-body"><span className="status-pill status-approved">{selected.status || (selected.available ? 'Available' : 'Occupied')}</span><h2>{selected.title}</h2><p className="property-location"><MapPin size={15}/>{selected.location}, {selected.city}</p><div className="modal-price">{money(selected.monthlyRent)} <small>/ month</small></div><div className="amenities"><span><BedDouble size={15}/>{selected.bedrooms} bedrooms</span><span><Bath size={15}/>{selected.bathrooms} bathrooms</span></div><p className="property-description">{selected.description || 'A considered home in a well-connected neighbourhood.'}</p><button className="btn-primary full-btn" onClick={() => { setSelected(null); if (!user) go('/login'); else if (role === 'tenant') setNotice('Application started. Your landlord can follow up in messages.'); else requireRole(['tenant']) }}>Contact about this home <ArrowRight size={15}/></button></div></div></div>}</section>
}

function PropertiesPage({ properties, setProperties, setModal, setEditing, setForm, setNotice }) {
  const [status, setStatus] = useState('All properties')
  const list = properties.filter(p => status === 'All properties' || p.status === status)
  function edit(p) { setEditing(p); setForm({ ...p, monthlyRent: String(p.monthlyRent), status: p.status || (p.available ? 'Available' : 'Occupied') }); setModal('property') }
  function cycleStatus(p) { const next = p.status === 'Available' ? 'Occupied' : p.status === 'Occupied' ? 'Under Maintenance' : 'Available'; setProperties(prev => prev.map(item => item.id === p.id ? { ...item, status: next, available: next === 'Available' } : item)); setNotice(`Listing moved to ${next.toLowerCase()}.`) }
  return <section className="dashboard-page"><PageHeading eyebrow="PROPERTY INVENTORY" title={<>Your properties, <i>at a glance.</i></>} subtitle="Keep every listing and home status up to date." action={<button className="btn-primary" onClick={() => { setEditing(null); setForm({ title: '', location: '', city: 'Hyderabad', propertyType: 'Apartment', monthlyRent: '', bedrooms: 2, bathrooms: 1, description: '', imageUrl: '', available: true, status: 'Available' }); setModal('property') }}><Plus size={16}/> Add property</button>}/><div className="inventory-summary"><div><span className="inventory-count">{properties.length}</span><span>Total homes</span></div><div><span className="inventory-count">{properties.filter(p => (p.status || (p.available ? 'Available' : 'Occupied')) === 'Available').length}</span><span>Available now</span></div><div><span className="inventory-count">{properties.filter(p => p.status === 'Occupied' || !p.available).length}</span><span>Occupied</span></div><div><span className="inventory-count">{properties.filter(p => p.status === 'Under Maintenance').length}</span><span>Maintenance</span></div></div><section className="surface-card inventory-surface"><div className="table-toolbar"><div><h2>All listings</h2><p>Manage your property's listing status and details.</p></div><label className="select-filter"><Filter size={14}/><select value={status} onChange={e => setStatus(e.target.value)}><option>All properties</option><option>Available</option><option>Occupied</option><option>Under Maintenance</option></select></label></div><PropertyTable properties={list} actions={p => <div className="row-actions"><button className="btn-quiet" onClick={() => edit(p)}>Edit</button><button className="btn-quiet" onClick={() => cycleStatus(p)}><MoreHorizontal size={17}/></button></div>}/>{!list.length && <Empty icon={Building2} title="No listings here yet" detail="Add a property to start building your portfolio."/>}</section><div className="info-note"><ShieldCheck size={16}/><span>Listing details save to this browser preview while the API is offline. Connect your backend for shared, permanent records.</span></div></section>
}

function ApplicationsPage({ role, applications, changeApplication, goNav }) {
  const [tab, setTab] = useState('All applications')
  const [view, setView] = useState('board')
  const filtered = applications.filter(a => tab === 'All applications' || (tab === 'In progress' ? ['PENDING', 'CHECKING'].includes(a.status) : a.status === tab.toUpperCase()))
  const stages = [{ id: 'PENDING', title: 'Applied', color: 'amber' }, { id: 'CHECKING', title: 'Background check', color: 'blue' }, { id: 'APPROVED', title: 'Approved', color: 'sage' }, { id: 'REJECTED', title: 'Rejected', color: 'rose' }]
  const tenantView = role === 'tenant'
  return <section className="dashboard-page"><PageHeading eyebrow={tenantView ? 'YOUR RENTAL JOURNEY' : 'TENANT MANAGEMENT'} title={tenantView ? <>Your rental <i>applications.</i></> : <>Applications, <i>made simple.</i></>} subtitle={tenantView ? 'Keep track of your applications and next steps.' : 'Review prospective tenants and move each application forward.'}/><div className="application-toolbar"><div className="segmented">{['All applications', 'In progress', 'Approved'].map(item => <button key={item} className={tab === item ? 'selected' : ''} onClick={() => setTab(item)}>{item}</button>)}</div>{!tenantView && <div className="view-switch"><button className={view === 'board' ? 'selected' : ''} onClick={() => setView('board')}>Board</button><button className={view === 'table' ? 'selected' : ''} onClick={() => setView('table')}>List</button></div>}</div>{tenantView || view === 'table' ? <section className="surface-card application-list">{filtered.map(app => <div className="application-list-row" key={app.id}><span className="person-avatar">{app.applicantName?.slice(0,1) || 'T'}</span><div className="applicant-copy"><b>{tenantView ? `Application for ${app.propertyTitle || 'your home'}` : app.applicantName}</b><small>{tenantView ? 'Sent ' + app.appliedAt : `${app.email} · ${app.propertyTitle || 'Property'}`}</small></div><span className={`status-pill ${statusClass(app.status)}`}><i/>{app.status === 'PENDING' ? 'Applied' : app.status === 'CHECKING' ? 'Background check' : app.status}</span>{!tenantView && <ApplicationActions app={app} changeApplication={changeApplication}/>}</div>)}{filtered.length === 0 && <Empty icon={ClipboardList} title="No applications to show" detail="Applications will appear here as soon as a tenant applies." action={<button className="btn-secondary" onClick={() => goNav('discover')}>Browse homes</button>}/>}</section> : <div className="kanban-board">{stages.map(stage => <div key={stage.id} className="kanban-column"><div className="kanban-heading"><span className={`stage-dot ${stage.color}`}/><b>{stage.title}</b><em>{applications.filter(a => a.status === stage.id).length}</em></div>{applications.filter(a => a.status === stage.id).map(app => <article className="applicant-card" key={app.id}><div className="applicant-card-top"><span className="person-avatar">{app.applicantName?.slice(0,1)}</span><button className="bare-icon" onClick={() => {}}>···</button></div><b>{app.applicantName}</b><small>{app.propertyTitle || 'Property application'}</small><span className="applicant-date"><Clock3 size={12}/>{app.appliedAt || 'Recently'}</span><ApplicationActions app={app} changeApplication={changeApplication}/></article>)}</div>)}</div>}<div className="info-note"><ShieldCheck size={16}/><span>Application changes sync to the property API when connected. Background-check status stays in this browser preview.</span></div></section>
}

function FinancesPage({ expenses, setModal, setNotice, properties }) {
  const [period, setPeriod] = useState('This month')
  const totalExpenses = expenses.reduce((sum, row) => sum + Number(row.amount), 0)
  const totalCollected = properties.filter(p => p.status === 'Occupied').reduce((sum, p) => sum + Number(p.monthlyRent || 0), 0) || 112000
  const totals = ['Repairs', 'Taxes', 'Utilities'].map(category => ({ category, total: expenses.filter(e => e.category === category).reduce((sum, e) => sum + Number(e.amount), 0) }))
  return <section className="dashboard-page"><PageHeading eyebrow="RENT & EXPENSES" title={<>Know where every <i>rupee goes.</i></>} subtitle="A clear monthly view of your rental income and costs." action={<button className="btn-primary" onClick={() => setModal('expense')}><Plus size={16}/> Log expense</button>}/><div className="finance-banner"><div><span className="finance-icon"><Wallet size={19}/></span><small>NET RENTAL INCOME · OCTOBER 2026</small><b>{money(totalCollected - totalExpenses)}</b><span className="positive"><ArrowUpRight size={13}/> 8.4% from last month</span></div><div className="finance-banner-right"><span>Portfolio performance</span><strong>{Math.max(0, 100 - Math.round(totalExpenses / Math.max(totalCollected, 1) * 100))}%</strong><div className="progress-track"><i style={{ width: `${Math.max(0, 100 - Math.round(totalExpenses / Math.max(totalCollected, 1) * 100))}%` }}/></div><small>Rent retained after expenses</small></div></div><div className="stat-grid three"><Metric icon={CircleDollarSign} label="Rent collected" value={money(totalCollected)} tone="sage" note="4 payments received"/><Metric icon={Clock3} label="Pending rent" value="₹32,000" tone="amber" note="Due Nov 1"/><Metric icon={ArrowDownRight} label="Expenses" value={money(totalExpenses)} tone="rose" note={`${expenses.length} logged this month`}/></div><div className="two-col"><section className="surface-card expense-breakdown"><CardHeading title="Expense breakdown" detail="By category this month" action={<button className="bare-link" onClick={() => setPeriod(period === 'This month' ? 'Last month' : 'This month')}>{period} <ChevronDown size={13}/></button>}/>{totals.map((item, index) => <div className="category-row" key={item.category}><span className={`category-icon cat-${index}`}><span>{index === 0 ? <Wrench size={16}/> : index === 1 ? <FileText size={16}/> : <Activity size={16}/>}</span></span><div><b>{item.category}</b><small>{expenses.filter(e => e.category === item.category).length} recorded entries</small></div><strong>{money(item.total)}</strong></div>)}<div className="expense-total"><span>Total expenses</span><b>{money(totalExpenses)}</b></div></section><section className="surface-card"><CardHeading title="Recent expenses" detail="Your latest outgoings" action={<button className="bare-link" onClick={() => setNotice('Showing all expense records.')}>View all <ArrowRight size={13}/></button>}/>{expenses.slice(0, 5).map(expense => <div className="expense-row" key={expense.id}><span className="expense-bullet"><ArrowDownRight size={15}/></span><div><b>{expense.label}</b><small>{expense.category} · {expense.date}</small></div><strong>−{money(expense.amount)}</strong></div>)}{expenses.length === 0 && <Empty icon={Wallet} title="No expenses logged" detail="Your property costs will appear here."/>}</section></div><div className="info-note"><CircleHelp size={16}/><span>Rent totals and expense entries in this view are a local finance preview. Connect a payment and ledger API for live financial records.</span></div></section>
}

function MessagesPage({ messages, activeChat, setActiveChat, activeConversation, messageDraft, setMessageDraft, sendMessage, role }) {
  return <section className="dashboard-page messages-page"><PageHeading eyebrow="HAVEN MESSAGES" title={<>A little more <i>in sync.</i></>} subtitle="Keep the conversation around your home in one place."/><div className="chat-shell"><aside className="chat-contacts"><div className="chat-list-heading"><b>Messages</b><span>{messages.length}</span></div><div className="chat-search"><Search size={15}/><input placeholder="Search conversations"/></div>{messages.map(chat => <button key={chat.id} className={`contact-row ${activeChat === chat.id ? 'active' : ''}`} onClick={() => setActiveChat(chat.id)}><span className="contact-avatar">{chat.initials}{chat.online && <i/>}</span><span className="contact-details"><b>{chat.name}</b><small>{chat.messages[chat.messages.length - 1]?.text}</small></span><span className="contact-meta"><small>{chat.messages[chat.messages.length - 1]?.time}</small></span></button>)}{messages.length === 0 && <Empty icon={MessageCircle} title="No conversations yet" detail="Start by connecting with a tenant or landlord."/>}</aside><section className="chat-main">{activeConversation ? <><div className="chat-header"><span className="contact-avatar">{activeConversation.initials}{activeConversation.online && <i/>}</span><div><b>{activeConversation.name}</b><small><span/> {activeConversation.online ? 'Online now' : 'Usually replies quickly'}</small></div><button className="bare-icon" aria-label="Conversation details"><MoreHorizontal size={19}/></button></div><div className="chat-context"><span className="soft-icon sage"><Home size={15}/></span><span><small>CONVERSATION ABOUT</small><b>{activeConversation.property}</b></span><button className="bare-link">View property <ArrowUpRight size={13}/></button></div><div className="message-thread"><div className="day-divider"><span>Today</span></div>{activeConversation.messages.map(message => <div key={message.id || message.time + message.text} className={`message-line ${message.from === 'me' ? 'mine' : ''}`}><div className="message-bubble">{message.text}<small>{message.time}</small></div></div>)}</div><form className="message-composer" onSubmit={sendMessage}><input value={messageDraft} onChange={e => setMessageDraft(e.target.value)} placeholder="Write a message…"/><span className="composer-hint">Enter to send</span><button className="send-button" type="submit" aria-label="Send message"><Send size={16}/></button></form></> : <Empty icon={MessageCircle} title="Choose a conversation" detail="Select a contact to see your messages."/>}</section></div><div className="info-note"><ShieldCheck size={16}/><span>Messages are saved in this browser preview. Connect a messaging service to enable live delivery between accounts.</span></div></section>
}

function UsersPage({ setNotice }) {
  const rows = [{ initials: 'AM', name: 'Aarav Mehta', email: 'aarav.m@example.com', role: 'Landlord', status: 'Active', joined: 'Oct 12, 2026' }, { initials: 'MN', name: 'Meera Nair', email: 'meera.n@example.com', role: 'Tenant', status: 'Active', joined: 'Oct 10, 2026' }, { initials: 'KS', name: 'Kabir Shah', email: 'kabir.s@example.com', role: 'Tenant', status: 'Active', joined: 'Oct 09, 2026' }, { initials: 'SI', name: 'Sana Iyer', email: 'sana.iyer@example.com', role: 'Tenant', status: 'Active', joined: 'Oct 07, 2026' }, { initials: 'PR', name: 'Priya Rao', email: 'priya.r@example.com', role: 'Landlord', status: 'Pending', joined: 'Oct 05, 2026' }]
  return <section className="dashboard-page"><PageHeading eyebrow="PLATFORM USERS" title={<>People make a <i>community.</i></>} subtitle="Review account activity and keep role access clear." action={<button className="btn-secondary" onClick={() => setNotice('User invitations are coming soon.')}><Plus size={15}/> Invite a user</button>}/><div className="stat-grid three"><Metric icon={Users} label="All users" value="1,284" tone="blue" note="Across all account types"/><Metric icon={House} label="Tenants" value="962" tone="sage" note="75% of the community"/><Metric icon={Building2} label="Landlords" value="322" tone="amber" note="Managing 1,142 listings"/></div><section className="surface-card inventory-surface"><div className="table-toolbar"><div><h2>All accounts</h2><p>Manage account roles and access status.</p></div><div className="searchbox compact-search"><Search size={15}/><input placeholder="Search people"/></div></div><div className="responsive-table"><table className="data-table"><thead><tr><th>NAME</th><th>ROLE</th><th>STATUS</th><th>JOINED</th><th/></tr></thead><tbody>{rows.map(row => <tr key={row.email}><td><div className="table-person"><span className="person-avatar">{row.initials}</span><span><b>{row.name}</b><small>{row.email}</small></span></div></td><td><span className="role-pill">{row.role}</span></td><td><span className={`status-pill ${row.status === 'Active' ? 'status-approved' : 'status-checking'}`}><i/>{row.status}</span></td><td>{row.joined}</td><td><button className="bare-icon" title="More options" onClick={() => setNotice(`Account menu for ${row.name}.`)}><MoreHorizontal size={18}/></button></td></tr>)}</tbody></table></div><div className="table-pagination"><span>Showing 5 of 1,284 users</span><div><button disabled>Previous</button><button>Next <ArrowRight size={13}/></button></div></div></section><div className="info-note"><ShieldCheck size={16}/><span>Role selection here is a client-side prototype. Enforce roles and account permissions in your backend before launch.</span></div></section>
}

function LoginPage({ authMode, setAuthMode, authRole, setAuthRole, authForm, setAuthForm, authError, showPassword, setShowPassword, submitAuth, demoSocial, go }) {
  return <div className="auth-layout"><section className="auth-story"><div className="auth-brand"><span className="brand-mark"><House size={19}/></span><b>haven<span>.</span></b></div><div className="auth-story-copy"><span className="eyebrow">RENTAL LIVING, REIMAGINED</span><h1>A better home<br/>for <i>what’s next.</i></h1><p>A calmer way to find a place, care for it, and feel at home.</p><div className="auth-quote"><div className="quote-stars">★★★★★</div><p>“Everything about finding my new home felt lighter. The whole process just made sense.”</p><div className="quote-person"><span className="person-avatar">MN</span><span><b>Meera Nair</b><small>Haven tenant since 2025</small></span></div></div></div><div className="auth-story-footer"><span>Thoughtful homes. Clearer days.</span><span>© 2026 Haven</span></div></section><section className="auth-panel"><div className="auth-panel-top"><button className="bare-link" onClick={() => go('/Act')}><ArrowRight className="back-arrow" size={14}/> Browse homes</button><div className="auth-mobile-brand"><span className="brand-mark"><House size={17}/></span><b>haven<span>.</span></b></div><span>Need help? <button className="bare-link" onClick={() => {}}>Contact us</button></span></div><div className="auth-card"><div className="auth-tabs"><button className={authMode === 'signin' ? 'selected' : ''} onClick={() => setAuthMode('signin')}>Sign in</button><button className={authMode === 'signup' ? 'selected' : ''} onClick={() => setAuthMode('signup')}>Create account</button></div><div className="auth-heading"><span className="eyebrow">WELCOME TO HAVEN</span><h2>{authMode === 'signin' ? 'Good to have you back.' : 'Let’s find your place.'}</h2><p>{authMode === 'signin' ? 'Sign in to your account to pick up where you left off.' : 'Create your account and make yourself at home.'}</p></div><form className="auth-form" onSubmit={submitAuth}>{authMode === 'signup' && <label>Your name<input required value={authForm.name} onChange={e => setAuthForm({ ...authForm, name: e.target.value })} placeholder="Your full name" autoComplete="name"/></label>}<label>Email address<input required type="email" value={authForm.email} onChange={e => setAuthForm({ ...authForm, email: e.target.value })} placeholder="you@example.com" autoComplete="email"/></label><label>Password<div className="password-input"><input required type={showPassword ? 'text' : 'password'} value={authForm.password} onChange={e => setAuthForm({ ...authForm, password: e.target.value })} placeholder="At least 4 characters" autoComplete={authMode === 'signin' ? 'current-password' : 'new-password'}/><button type="button" onClick={() => setShowPassword(!showPassword)} aria-label="Toggle password visibility">{showPassword ? <EyeOff size={16}/> : <Eye size={16}/>}</button></div></label><div className="role-select-label"><span>Your account type</span><small>Choose the view that fits you</small></div><div className="role-options">{['tenant', 'landlord', 'admin'].map(item => <button type="button" key={item} className={authRole === item ? 'selected' : ''} onClick={() => setAuthRole(item)}><span className="role-icon">{item === 'tenant' ? <KeyRound size={16}/> : item === 'landlord' ? <Building2 size={16}/> : <ShieldCheck size={16}/>}</span><span><b>{roleName[item]}</b><small>{item === 'tenant' ? 'Find and manage your home' : item === 'landlord' ? 'Manage your properties' : 'Manage the platform'}</small></span>{authRole === item && <span className="role-check"><Check size={12}/></span>}</button>)}</div>{authError && <div className="auth-error">{authError}</div>}<button className="btn-primary auth-submit" type="submit">{authMode === 'signin' ? 'Sign in to Haven' : 'Create your account'} <ArrowRight size={16}/></button></form><div className="auth-divider"><span/>or continue with<span/></div><div className="social-buttons"><button onClick={() => demoSocial('Google')}><b className="google-g">G</b>Google</button><button onClick={() => demoSocial('Apple')}><b className="apple-mark">●</b>Apple</button></div><p className="auth-legal">By continuing, you agree to Haven’s <button>Terms</button> and <button>Privacy Policy</button>.</p><div className="demo-hint"><Sparkles size={14}/><span>Preview mode: use any email and a password of 4+ characters to explore each role.</span></div></div><div className="auth-panel-footer">Secure sign-in <span>·</span> Your home, your way</div></section></div>
}

function PageHeading({ eyebrow, title, subtitle, action }) { return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{action}</div> }
function Metric({ icon: Icon, label, value, tone = 'sage', change, note }) { return <article className="metric-card"><div className="metric-top"><span className={`metric-icon ${tone}`}><Icon size={18}/></span>{change && <span className={change.includes('%') ? 'metric-change' : 'metric-note'}>{change.includes('%') && <ArrowUpRight size={12}/>} {change}</span>}</div><span className="metric-label">{label}</span><b className="metric-value">{value}</b><small>{note || ''}</small></article> }
function CardHeading({ title, detail, action }) { return <div className="card-heading"><div><h2>{title}</h2><p>{detail}</p></div>{action}</div> }
function ActivityRow({ icon: Icon, title, detail, time }) { return <div className="activity-row"><span className="activity-icon"><Icon size={15}/></span><div><b>{title}</b><small>{detail}</small></div><time>{time}</time></div> }
function Attention({ icon: Icon, title, detail, action, onClick }) { return <div className="attention-row"><span><Icon size={15}/></span><div><b>{title}</b><small>{detail}</small></div><button onClick={onClick}>{action} <ArrowRight size={12}/></button></div> }
function UserRow({ initials, name, email, role }) { return <div className="user-row"><span className="person-avatar">{initials}</span><div><b>{name}</b><small>{email}</small></div><span className="role-pill">{role}</span></div> }
function statusClass(status) { return status === 'APPROVED' ? 'status-approved' : status === 'REJECTED' ? 'status-rejected' : status === 'CHECKING' ? 'status-checking' : 'status-pending' }
function ApplicationActions({ app, changeApplication }) { return <div className="application-actions"><button className="btn-quiet" onClick={() => changeApplication(app, app.status === 'PENDING' ? 'CHECKING' : 'APPROVED')}>{app.status === 'PENDING' ? 'Start check' : app.status === 'CHECKING' ? 'Approve' : 'Review'}</button>{!['APPROVED', 'REJECTED'].includes(app.status) && <button className="btn-icon-quiet" onClick={() => changeApplication(app, 'REJECTED')} title="Reject application"><X size={15}/></button>}</div> }
function PropertyCard({ property, onClick, index = 0 }) { const status = property.status || (property.available ? 'Available' : 'Occupied'); return <button className="property-card" onClick={onClick}><div className="property-card-image"><img src={property.imageUrl || photos[index % photos.length]} alt={property.title} onError={e => { e.currentTarget.src = photos[index % photos.length] }}/><span className={`status-pill ${status === 'Available' ? 'status-approved' : status === 'Under Maintenance' ? 'status-pending' : 'status-occupied'}`}><i/>{status}</span><span className="property-image-arrow"><ArrowUpRight size={16}/></span></div><div className="property-card-info"><span className="eyebrow">{property.propertyType || 'Home'} <i>·</i> {property.bedrooms || 1} bedroom{property.bedrooms === 1 ? '' : 's'}</span><h3>{property.title}</h3><p><MapPin size={13}/>{property.location}, {property.city}</p><div className="property-card-bottom"><b>{money(property.monthlyRent)}<small> / month</small></b><span>View home <ArrowRight size={13}/></span></div></div></button> }
function PropertyTable({ properties, actions }) { return <div className="responsive-table"><table className="data-table"><thead><tr><th>PROPERTY</th><th>STATUS</th><th>MONTHLY RENT</th><th>TYPE</th><th/></tr></thead><tbody>{properties.map(p => <tr key={p.id}><td><div className="table-property"><img src={p.imageUrl || photos[0]} alt=""/><span><b>{p.title}</b><small>{p.location}, {p.city}</small></span></div></td><td><span className={`status-pill ${(p.status || (p.available ? 'Available' : 'Occupied')) === 'Available' ? 'status-approved' : p.status === 'Under Maintenance' ? 'status-pending' : 'status-occupied'}`}><i/>{p.status || (p.available ? 'Available' : 'Occupied')}</span></td><td className="rent-cell">{money(p.monthlyRent)}</td><td>{p.propertyType || 'Home'}</td><td>{actions ? actions(p) : <button className="bare-icon" aria-label="Open property"><ArrowUpRight size={15}/></button>}</td></tr>)}</tbody></table></div> }
function MiniChart() { return <div className="chart-wrap"><div className="chart-y-labels"><span>₹1.5L</span><span>₹1.0L</span><span>₹50k</span><span>₹0</span></div><div className="chart-area"><div className="chart-grid"><i/><i/><i/><i/></div><svg viewBox="0 0 600 150" preserveAspectRatio="none" role="img" aria-label="Rental activity trend"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#9db69a" stopOpacity=".23"/><stop offset="100%" stopColor="#9db69a" stopOpacity="0"/></linearGradient></defs><path className="chart-fill" d="M0 112 C45 105 55 88 100 96 S160 75 200 80 S260 64 300 74 S360 39 400 52 S460 68 500 34 S560 41 600 15 V150 H0Z"/><path className="chart-line" d="M0 112 C45 105 55 88 100 96 S160 75 200 80 S260 64 300 74 S360 39 400 52 S460 68 500 34 S560 41 600 15"/><path className="chart-line secondary" d="M0 128 C45 122 55 110 100 117 S160 100 200 110 S260 94 300 103 S360 85 400 91 S460 100 500 77 S560 87 600 64"/></svg><div className="chart-x-labels"><span>Oct 01</span><span>Oct 05</span><span>Oct 10</span><span>Oct 15</span><span>Oct 20</span><span>Oct 25</span><span>Oct 31</span></div></div></div> }
function Empty({ icon: Icon, title, detail, action }) { return <div className="empty-state"><span><Icon size={21}/></span><h3>{title}</h3><p>{detail}</p>{action}</div> }

